"""
BarberQueue Auto-Unpacker for Cloud Deployments (Render / Railway / VPS)
Embeds all HTML templates, static files, and workflows inside a single Python module.
"""
import os, io, zipfile, base64

ASSETS_B64 = """"""

def unpack_if_needed():
    # If templates directory is missing or empty, unpack automatically
    if not os.path.exists('templates') or not os.listdir('templates'):
        data = base64.b64decode(ASSETS_B64)
        buf = io.BytesIO(data)
        with zipfile.ZipFile(buf, 'r') as z:
            z.extractall('.')
        print('[Assets Unpacker] Unpacked templates, static assets and configs successfully!')

# Automatically unpack upon import
unpack_if_needed()
